            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            try
            {
                DeepCopyInInternal(
                    item: item,
                    rhs: rhs,
                    errorMask: errorMask,
                    copyMask: copyMask,
                    deepCopy: deepCopy);
            }
            catch (Exception ex)
            {
                throw RecordException.Enrich(ex, rhs);
            }
        }
        
        private void DeepCopyInInternal(
            IPerk item,
            IPerkGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            base.DeepCopyIn(
                (IFallout3MajorRecord)item,
                (IFallout3MajorRecordGetter)rhs,
                errorMask,
                copyMask,
                deepCopy: deepCopy);
            if ((copyMask?.GetShouldTranslate((int)Perk_FieldIndex.Name) ?? true))
            {
                item.Name = rhs.Name;
            }
            if ((copyMask?.GetShouldTranslate((int)Perk_FieldIndex.Description) ?? true))
            {
                item.Description = rhs.Description;
            }
            if ((copyMask?.GetShouldTranslate((int)Perk_FieldIndex.Icons) ?? true))
            {
                errorMask?.PushIndex((int)Perk_FieldIndex.Icons);
                try
                {
                    if(rhs.Icons is {} rhsIcons)
                    {
