                                errorMask: errorMask,
                                default(TranslationCrystal));
                        }));
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Perk_FieldIndex.PerkData) ?? true))
            {
                errorMask?.PushIndex((int)Perk_FieldIndex.PerkData);
                try
                {
                    if ((copyMask?.GetShouldTranslate((int)Perk_FieldIndex.PerkData) ?? true))
                    {
                        item.PerkData = rhs.PerkData.DeepCopy(
                            copyMask: copyMask?.GetSubCrystal((int)Perk_FieldIndex.PerkData),
                            errorMask: errorMask);
                    }
                }
                catch (Exception ex)
                when (errorMask != null)
                {
                    errorMask.ReportException(ex);
                }
                finally
                {
                    errorMask?.PopIndex();
                }
            }
            if ((copyMask?.GetShouldTranslate((int)Perk_FieldIndex.Effects) ?? true))
            {
                errorMask?.PushIndex((int)Perk_FieldIndex.Effects);
                try
